pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address receiver, uint256 amount, address actor) public {
        // The admissible domain: sender is not the owner (so the invariant is tested on unauthorized calls)
        vm.assume(actor != address(0) && actor != address(c));
        (bool ownerOk, bytes memory ownerData) =
            address(c).call(abi.encodeWithSignature("owner()"));
        address owner;
        if (ownerOk && ownerData.length == 32) {
            owner = abi.decode(ownerData, (address));
        } else {
            owner = address(0);
        }
        vm.assume(actor != owner);

        // Record the initial contract balance
        uint256 initialBalance = address(c).balance;

        // Give the actor some ETH to send
        vm.deal(actor, amount);
        vm.prank(actor);
        // In the reference (correct) contract this call will revert because actor != owner,
        // so the balance stays unchanged. The mutant allows it, so balance decreases by amount.
        try c.sendTo(receiver, amount) {} catch {}

        uint256 finalBalance = address(c).balance;

        // Invariant: balance never decreases under an unauthorized sendTo (actor != owner)
        assertTrue(finalBalance == initialBalance);
    }
}

