pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address receiver) public {
        // restrict amount to avoid overflows and keep it admissible
        vm.assume(amount > 0 && amount <= address(this).balance);
        // deploy a contract that rejects incoming Ether via revert in fallback
        Reverter adversarial = new Reverter();
        address target = receiver == address(adversarial) ? address(0x1) : receiver;
        // fund the contract with more than amount
        vm.deal(address(c), amount + 1 ether);
        uint256 balanceBefore = address(c).balance;
        // owner (this contract) calls sendTo
        c.sendTo(target, amount);
        uint256 balanceAfter = address(c).balance;
        // For the reference contract with transfer, it must succeed for EOAs (target) or fail with revert for the adversarial contract.
        // When target is not adversarial, transfer succeeds and balance decreases by amount.
        // When target is adversarial, transfer reverts so balance remains unchanged.
        // For the buggy version with send, when target is adversarial, send returns false but does not revert, so balance remains unchanged — but the rule we assert below checks consistency.
        // The general rule: if the call did not revert, balanceAfter == balanceBefore - amount.
        bool reverted = false;
        try this.indicator(c, target, amount) { reverted = false; } catch { reverted = true; }
        if (!reverted) {
            assertTrue(balanceAfter == balanceBefore - amount);
        }
    }
    function indicator(C _c, address target, uint256 amount) external {
        _c.sendTo(target, amount);
    }
}

contract Reverter {
    fallback() external payable { revert(); }
}

