pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address receiver) public {
        // Exclude zero amount to avoid trivial no-change, and bound to avoid overflow in vm.deal
        vm.assume(amount > 0);
        vm.assume(amount <= address(this).balance);
        // Owner is the setUp caller (this contract), so we need to fund the contract first
        // Since sendTo uses transfer which requires contract to have ether, we deal ether to the contract
        vm.deal(address(c), amount);
        uint256 balanceBefore = address(c).balance;
        // Owner calls sendTo
        c.sendTo(receiver, amount);
        uint256 balanceAfter = address(c).balance;
        // The contract's balance must decrease by exactly amount
        assertTrue(balanceAfter == balanceBefore - amount);
    }
}

