pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address receiver) public {
        // Ensure amount is non-zero and receiver is not zero to avoid trivial success.
        vm.assume(amount > 0);
        vm.assume(receiver != address(0));
        // The contract requires msg.sender == owner; we use the contract deployer as the owner
        // because the constructor sets owner to msg.sender (the test contract is the deployer).
        vm.assume(receiver != address(c)); // avoid sending to self, which could interfere with balance tracking

        // Fund the contract so it has ether to send
        uint256 fundAmt = amount + 1;
        vm.deal(address(c), fundAmt);

        // Record receiver's balance before the call
        uint256 balBefore = receiver.balance;

        // Owner calls sendTo
        vm.prank(address(this));
        c.sendTo(receiver, amount);

        // Record receiver's balance after the call
        uint256 balAfter = receiver.balance;

        // The invariant: the receiver's balance must have increased by exactly `amount`.
        // The reference contract sends `amount`, so this holds; the mutant sends 0, breaking it.
        assertTrue(balAfter == balBefore + amount);
    }
}

